{
  "vulnerable_symbols": [
    "axios.request",
    "axios.get",
    "axios.post"
  ],
  "trigger": "当使用 fetch 适配器并配置有限 maxContentLength/maxBodyLength 时，超大 data: URL、攻击者控制请求体或恶意服务器超大响应可绕过限制导致资源耗尽。",
  "preconditions": [
    "请求通过 axios 的 fetch 适配器发送（adapter: 'fetch'、adapter 数组选中 fetch、无 xhr/http 时回退 fetch 或 env.fetch）",
    "已配置有限的 maxContentLength 或 maxBodyLength（非默认 -1）",
    "应用依赖 axios 对这些大小限制进行强制校验"
  ],
  "exploit_evidence": [
    {
      "src": 3,
      "kind": "poc",
      "quote": "💣 PoC: Public Proof of Concept - Indicates if functional exploit code is publicly available, drastically increasing the risk of immediate attacks."
    }
  ],
  "fixed_version": "1.16.0",
  "summary_zh": "axios fetch 适配器未限制请求/响应大小，可致资源耗尽，升级 1.16.0。"
}
